    public static partial ZeroStatus zero_server_check_table(ulong server, ulong app);

    /// <summary>Binds and starts one core per worker index, and returns once listening.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Io` when the address does not resolve or cannot be bound or a thread cannot start; `InvalidArgument` when the server already started or is starting; `Closed` once a stop began or for an unknown server. A start that fails leaves the server ready with its targets attached.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_start(ulong server);

    /// <summary>Writes the address the server listens on, as `host:port` with an IPv6 host in brackets.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id. * `address_out` - receives the address, an owned string the caller releases with `zero_string_free`.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Closed` before the start, after the stop, or for an unknown server; `InvalidArgument` for a NULL or misaligned `address_out`.</para>
    /// <para>Safety</para>
    /// <para>`address_out` must be NULL or point to a writable `ZeroString *`.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_address(ulong server, nint* address_out);

    /// <summary>Writes the global worker indexes the server claimed, one per core in core order; a target attaches to one of them.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id. * `workers_out` - receives the indexes; NULL is accepted when `cap` is 0. * `cap` - how many indexes `workers_out` holds. * `count_out` - receives the number of indexes, also when `cap` is too small.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Limit` when `cap` is smaller than the count, after writing `count_out`; `InvalidArgument` for a NULL or misaligned output; `Closed` for an unknown server.</para>
    /// <para>Safety</para>
    /// <para>`workers_out` must be NULL or point to `cap` writable octets, and `count_out` NULL or a writable `uintptr_t`.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_workers(ulong server, byte* workers_out, nuint cap, nuint* count_out);

    /// <summary>Requests the drain and returns at once: the cores stop accepting, finish their in-flight requests within the drain deadline, and the server stops. A server that never started stops now.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id. * `drain_ms` - the longest the drain may take: `ZERO_NONE`, or at least the server's `drainMs` option, which is the deadline the cores apply.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Unsupported` for a drain shorter than the server's `drainMs` option, which this version cannot apply; `Closed` for an unknown server.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_shutdown(ulong server, ulong drain_ms);

    /// <summary>Blocks until the server stopped.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id. * `timeout_ms` - the longest wait in milliseconds; `ZERO_NONE` waits as long as it takes.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok` once the server stopped, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Timeout` when the server is still running when the timeout passes; `InvalidArgument` on an I/O worker thread and, until a stop began, on a thread bound to one of the server's targets, since the drain needs that thread's acknowledgments; `Closed` for an unknown server.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_wait(ulong server, ulong timeout_ms);

    /// <summary>Writes a server's statistics, summed over its worker indexes; once it stopped, those it had when it gave its indexes back.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id. * `stats_out` - receives the statistics; its `size` is set before the call.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`InvalidArgument` for a NULL or misaligned `stats_out` or a `size` below the version 1 size; `Closed` for an unknown server.</para>
    /// <para>Safety</para>
    /// <para>`stats_out` must be NULL or point to a writable struct of at least its `size` octets.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_stats(ulong server, ZeroStats* stats_out);

    /// <summary>Releases a server's id once the server is not running. A server that never started gives its worker indexes back.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Limit` while the server runs, its drain included; `Closed` for an unknown or freed server.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_server_free(ulong server);

    /// <summary>Pins a slot for the calling thread: while the pin is held the slot is not retired, so the views the thread reads stay valid, and a body region can be opened. A thread holds at most 64 pins; one that exits holding pins releases them.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `slot` - the slot's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Closed` unless the slot is leased or completing at the id's generation; `InvalidArgument` for a slot the thread already pinned or an id above `ZERO_ID_MAX`; `Limit` when the thread holds 64 pins or the slot counts the most pins it can.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_slot_pin(ulong slot);

    /// <summary>Releases the calling thread's pin on a slot.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `slot` - the slot's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`InvalidArgument` unless the calling thread pinned that id, or for an id above `ZERO_ID_MAX`.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_slot_unpin(ulong slot);

    /// <summary>Writes the route id a slot's request matched, from any thread.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `slot` - the slot's id. * `route_out` - receives the route id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Closed` unless the slot is leased or completing at the id's generation; `InvalidArgument` for an id above `ZERO_ID_MAX` or a NULL or misaligned `route_out`.</para>
    /// <para>Safety</para>
    /// <para>`route_out` must be NULL or point to a writable `uint32_t`.</para>
    /// </remarks>
    [LibraryImport(Library)]
    [SuppressGCTransition]
    public static partial ZeroStatus zero_slot_route(ulong slot, uint* route_out);

    /// <summary>Writes whether a slot's request was canceled: its connection or its target went away, so its lease was closed and later writes are refused. A host may stop working on a canceled request.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `slot` - the slot's id. * `canceled_out` - receives 1 for a canceled or closed lease, 0 otherwise.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Closed` for a stale or unknown id, including a lease the worker already retired; `InvalidArgument` for an id above `ZERO_ID_MAX` or a NULL `canceled_out`.</para>
    /// <para>Safety</para>
    /// <para>`canceled_out` must be NULL or point to a writable `uint8_t`.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_slot_canceled(ulong slot, byte* canceled_out);

    /// <summary>Attaches a pull target to one of a server's worker indexes, or to every one of them served from one queue. A worker index has at most one target.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `server` - the server's id. * `worker` - a global worker index from `zero_server_workers`, or `ZERO_ALL_WORKERS`. * `target_out` - receives the target's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`InvalidArgument` for a worker index of another server or outside the indexes; `Limit` when a worker index already has a target; `Closed` once a stop of the server began, or for an unknown server.</para>
    /// <para>Safety</para>
    /// <para>`target_out` must be NULL or point to a writable `uint64_t`.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_target_attach(ulong server, uint worker, ulong* target_out);

    /// <summary>Waits for the next batch of a target and copies it out.</summary>
    /// <remarks>
    /// <para>The first thread to poll binds the target. A request batch writes its slot ids to `slots` and their route ids to `routes`; an event batch writes one `ZeroEvent` per event to `events`, `event_size` octets apart, whose payloads stay valid until the next poll on this target or its detach. `batch_out` says which and how many.</para>
    /// <para>Arguments</para>
    /// <para>* `target` - the target's id. * `timeout_ms` - how long to wait in milliseconds; 0 checks once, `ZERO_NONE` waits as long as it takes. * `batch_out` - receives the batch; its `size` is set before the call. * `slots` - receives a request batch's slot ids, `cap` entries. * `routes` - receives their route ids, `cap` entries. * `events` - receives an event batch's records, `cap` entries. * `event_size` - the size of one `ZeroEvent` as the host built the array. * `cap` - the entries each array holds, at least `ZERO_MAX_BATCH`.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok` with a batch written, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Timeout` when nothing arrived in time or `zero_target_wake` ended the wait; `Closed` once the target is detached or its server stopped, or for an unknown target; `InvalidArgument` on an I/O worker thread, on a thread other than the bound one, for a `cap` below `ZERO_MAX_BATCH`, an `event_size` below the version 1 size, or an output the rules refuse.</para>
    /// <para>Safety</para>
    /// <para>`batch_out` must be NULL or a writable struct of at least its `size` octets; `slots`, `routes` and `events` must be NULL or writable arrays of `cap` entries, those of `events` `event_size` octets each.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_target_poll(ulong target, ulong timeout_ms, ZeroBatch* batch_out, ulong* slots, uint* routes, ZeroEvent* events, nuint event_size, nuint cap);

    /// <summary>Ends a poll blocked on a target with `ZeroStatus_Timeout`, or the next poll when none is blocked.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `target` - the target's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Closed` for an unknown or detached target.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_target_wake(ulong target);

    /// <summary>Detaches a target: the worker indexes it serves close its leases and answer them 503, fail its queued requests the same way, and release the slots it held. The id is released and the target's event views end. The target's thread holds no view through it afterward and makes no view call through it.</summary>
    /// <remarks>
    /// <para>Arguments</para>
    /// <para>* `target` - the target's id.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`Closed` for an unknown or detached target.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_target_detach(ulong target);

    /// <summary>Hands answered slots back to their worker and, from the thread bound to the worker's target, acknowledges a batch.</summary>
    /// <remarks>
    /// <para>Each id is checked on its own: an id above `ZERO_ID_MAX` or of another worker index is `InvalidArgument`, and a stale id or a slot neither leased nor completing is `Closed`. The accepted ids are applied with one wake of the worker per 256 ids. A slot completed without a response is answered 500 `NO_RESPONSE`. An acknowledgment is accepted only from the bound thread, for the epoch after the last one acknowledged; a refused one changes nothing but is reported, and the ids of the call are applied anyway.</para>
    /// <para>Arguments</para>
    /// <para>* `worker` - the worker index the ids belong to, `ZeroBatch.worker`. * `slots` - the answered slot ids. * `count` - how many. * `epoch` - the epoch to acknowledge, or `ZERO_EPOCH_NONE`. * `results_out` - NULL, or receives the status of each id, `count` entries, also when the call fails.</para>
    /// <para>Returns</para>
    /// <para>`ZeroStatus_Ok`, or a refusal.</para>
    /// <para>Errors</para>
    /// <para>`InvalidArgument` for a worker index of 128 or more, a refused acknowledgment (from another thread or out of order), or an argument the rules refuse; `Closed` for a worker index no server claimed.</para>
    /// <para>Safety</para>
    /// <para>`slots` must be a readable array of `count` ids, and `results_out` NULL or a writable array of `count` statuses.</para>
    /// </remarks>
    [LibraryImport(Library)]
    public static partial ZeroStatus zero_batch_complete(byte worker, ulong* slots, nuint count, ulong epoch, ZeroStatus* results_out);
}
